local WateringCanMaker = {}
local PRODUCTS = {
    iron_watering_can = { name = "Železna zalivalka", ironCost = 2, woodCost = 1, leatherCost = 1, time = 5, cost = 150, prestige = 3, happiness = 1, description = "Železna zalivalka za vrtnine." },
    bronze_watering_can = { name = "Bronasta zalivalka", bronzeCost = 2, ironCost = 1, woodCost = 1, leatherCost = 1, time = 7, cost = 360, prestige = 5, happiness = 2, description = "Bronasta zalivalka za večje vrtove." },
    silver_watering_can = { name = "Srebrna zalivalka", silverCost = 2, bronzeCost = 1, ironCost = 1, woodCost = 1, leatherCost = 1, time = 11, cost = 850, prestige = 10, happiness = 3, description = "Srebrna zalivalka za plemiške vrtove." },
    gilded_watering_can = { name = "Pozlačena zalivalka", goldCost = 1, silverCost = 2, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 15, cost = 1820, prestige = 19, happiness = 4, description = "Pozlačena zalivalka za dvorne vrtove." },
    jewel_set_watering_can = { name = "Draguljasta zalivalka", goldCost = 2, silverCost = 2, jewelCost = 1, bronzeCost = 1, woodCost = 1, leatherCost = 1, time = 19, cost = 3920, prestige = 35, happiness = 6, description = "Draguljasta zalivalka za kraljeve vrtove." },
    royal_sovereign_watering_can = { name = "Kraljevski suverena zalivalka", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 2, leatherCost = 1, time = 26, cost = 8400, prestige = 68, happiness = 12, description = "Suverena zalivalka z biseri za krono." },
}
local BUILDINGS = {
    watering_workshop = { name = "Zalivalna delavnica", cost = { gold = 340, wood = 175, stone = 135, iron = 7 }, upkeep = 6, qualityBonus = 5 },
    watering_house = { name = "Zalivalna hiša", cost = { gold = 1220, wood = 355, stone = 270, silver = 7, iron = 7 }, upkeep = 26, qualityBonus = 18 },
    master_watering_atelier = { name = "Mojstrski zalivalni atelje", cost = { gold = 3050, wood = 415, stone = 520, silver = 35, gold = 7 }, upkeep = 72, qualityBonus = 30 },
    sovereign_watering_palace = { name = "Suverena zalivalna palača", cost = { gold = 13000, wood = 630, stone = 830, gold = 83, jewel = 19 }, upkeep = 255, qualityBonus = 55, prestigeBonus = 50 },
}
WateringCanMaker.ironStock = 12; WateringCanMaker.bronzeStock = 10; WateringCanMaker.woodStock = 14; WateringCanMaker.leatherStock = 10; WateringCanMaker.silverStock = 8; WateringCanMaker.goldStock = 6; WateringCanMaker.jewelStock = 4; WateringCanMaker.pearlStock = 4
WateringCanMaker.productStock = {}; WateringCanMaker.buildings = {}; WateringCanMaker.maker = nil; WateringCanMaker.activeMaking = {}; WateringCanMaker.totalProducts = 0; WateringCanMaker.dayTimer = 0
function WateringCanMaker.init() WateringCanMaker.ironStock=12; WateringCanMaker.bronzeStock=10; WateringCanMaker.woodStock=14; WateringCanMaker.leatherStock=10; WateringCanMaker.silverStock=8; WateringCanMaker.goldStock=6; WateringCanMaker.jewelStock=4; WateringCanMaker.pearlStock=4; WateringCanMaker.productStock={}; WateringCanMaker.buildings={}; WateringCanMaker.maker=nil; WateringCanMaker.activeMaking={}; WateringCanMaker.totalProducts=0; WateringCanMaker.dayTimer=0; print("[WateringCanMaker] Royal Watering Can Maker System initialized (6 products, 4 buildings)") end
function WateringCanMaker.hireMaker(n,s) s=s or math.random(55,90); local c=590+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; WateringCanMaker.maker={name=n or ("Zalivalec "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zalivalec najet: %s (spretnost: %d)",WateringCanMaker.maker.name,s),"success") end; return true end
function WateringCanMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function WateringCanMaker.build(id) local ok,e=WateringCanMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(WateringCanMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function WateringCanMaker.getQualityBonus() local b=0; for _,bd in ipairs(WateringCanMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function WateringCanMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and WateringCanMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and WateringCanMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and WateringCanMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and WateringCanMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and WateringCanMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and WateringCanMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and WateringCanMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and WateringCanMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #WateringCanMaker.buildings==0 then return false,"Potrebna zalivalna delavnica" end; if not WateringCanMaker.maker then return false,"Potreben zalivalec" end; return true end
function WateringCanMaker.make(pt,qty) qty=qty or 1; local ok,e=WateringCanMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then WateringCanMaker.ironStock=WateringCanMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then WateringCanMaker.bronzeStock=WateringCanMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then WateringCanMaker.woodStock=WateringCanMaker.woodStock-d.woodCost*qty end; if d.leatherCost then WateringCanMaker.leatherStock=WateringCanMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then WateringCanMaker.silverStock=WateringCanMaker.silverStock-d.silverCost*qty end; if d.goldCost then WateringCanMaker.goldStock=WateringCanMaker.goldStock-d.goldCost*qty end; if d.jewelCost then WateringCanMaker.jewelStock=WateringCanMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then WateringCanMaker.pearlStock=WateringCanMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if WateringCanMaker.maker then t=math.max(1,t-math.floor(WateringCanMaker.maker.skill/13)) end; table.insert(WateringCanMaker.activeMaking,{id="watering_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function WateringCanMaker.completeMaking(m) local q=1.0+(WateringCanMaker.getQualityBonus()/100); if WateringCanMaker.maker then q=q+(WateringCanMaker.maker.skill/140) end; q=math.min(2.5,q); WateringCanMaker.productStock[m.productType]=(WateringCanMaker.productStock[m.productType] or 0)+m.quantity; WateringCanMaker.totalProducts=WateringCanMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if WateringCanMaker.maker then WateringCanMaker.maker.itemsMade=WateringCanMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then WateringCanMaker.maker.skill=math.min(100,WateringCanMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Zalivalka izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"watering.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function WateringCanMaker.update(dt) if not _G.state then return end; WateringCanMaker.dayTimer=WateringCanMaker.dayTimer+dt; if WateringCanMaker.dayTimer>=30 then WateringCanMaker.dayTimer=0; for i=#WateringCanMaker.activeMaking,1,-1 do local m=WateringCanMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then WateringCanMaker.completeMaking(m); table.remove(WateringCanMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(WateringCanMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if WateringCanMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function WateringCanMaker.getStats() return {ironStock=WateringCanMaker.ironStock,bronzeStock=WateringCanMaker.bronzeStock,woodStock=WateringCanMaker.woodStock,leatherStock=WateringCanMaker.leatherStock,silverStock=WateringCanMaker.silverStock,goldStock=WateringCanMaker.goldStock,jewelStock=WateringCanMaker.jewelStock,pearlStock=WateringCanMaker.pearlStock,productStock=WateringCanMaker.productStock,numBuildings=#WateringCanMaker.buildings,hasMaker=WateringCanMaker.maker~=nil,makerName=WateringCanMaker.maker and WateringCanMaker.maker.name or "—",makerSkill=WateringCanMaker.maker and WateringCanMaker.maker.skill or 0,activeMaking=#WateringCanMaker.activeMaking,totalProducts=WateringCanMaker.totalProducts} end
return WateringCanMaker
